-- BMLT NHPC: Electrolytes, Blood Gas & Acid–Base Balance (25 MCQ + 25 Mock)
begin;
on conflict (content_id) do nothing;
commit;
select content_type,count(*) from public.learning_content
where faculty='BMLT' and subject='BMLT NHPC Licensing'
and content_data->>'topic'='Electrolytes, Blood Gas & Acid–Base Balance'
group by content_type;
